import { TfiStatsCollector } from './tfistatscollector';

/**
 * Global register function
 */
export function loadStats() {
    console.log("CollectorJS: Attach stats collector hook called v=1.1.2");
    let statsCollector = new TfiStatsCollector(null, null);
    statsCollector.registerGlobals();
}

let windowElement = window[addEventListener ? 'addEventListener' : 'attachEvent'];
windowElement(addEventListener ? 'load' : 'onload', loadStats);