import { BrowserDetection, BrowserInfo } from "../utils";
import {
    IObservedEvent,
    StatsProcessingStatus,
    WebRTCAudioStat,
    WebRTCNetworkStat, WebRTCStats,
    WebRTCVideoStat
} from "../model";

import { MetricsTransporterFunction, MockTransport, TransportInterface } from "../transport";
import { MockTagsProvider, TagsProviderFunction, TagsProviderInterface } from "../tags";

interface RTCStatsReport extends ReadonlyMap<string, any> { }

const rfactorConstants = {
    r0: 94.768,
    is: 1.42611
};

export class TfiStatsCollector {
    private tagsProvider: TagsProviderInterface;
    private transporter: TransportInterface;
    private tagsProviderFn: TagsProviderFunction;
    private transporterFn: MetricsTransporterFunction;
    private browserInfo: BrowserInfo;
    private readonly ssrcLocalVideoStatsMap: Map<string, WebRTCVideoStat>;
    private readonly ssrcRemoteVideoStatsMap: Map<string, WebRTCVideoStat>;
    private readonly ssrcLocalAudioStatsMap: Map<string, WebRTCAudioStat>;
    private readonly ssrcRemoteAudioStatsMap: Map<string, WebRTCAudioStat>;
    private readonly transportStatsMap: Map<string, WebRTCNetworkStat>;
    private isLegacy: boolean = true;

    constructor(transporter: TransportInterface, tagsProvider: TagsProviderInterface) {
        this.tagsProvider = tagsProvider;
        this.transporter = transporter;
        this.ssrcLocalVideoStatsMap = new Map<string, WebRTCVideoStat>();
        this.ssrcRemoteVideoStatsMap = new Map<string, WebRTCVideoStat>();
        this.ssrcLocalAudioStatsMap = new Map<string, WebRTCAudioStat>();
        this.ssrcRemoteAudioStatsMap = new Map<string, WebRTCAudioStat>();
        this.transportStatsMap = new Map<string, WebRTCNetworkStat>();
    }

    /**
     * set the transporter to send the metrics
     * @param transporter
     */
    public setTransport(transporter: TransportInterface): void {
        this.transporter = transporter;
        this.transporterFn = transporter.push;
    }

    /**
     * set the transporter function to send the metrics
     * @param transporter
     */
    public setTransportFn(transporterFn: MetricsTransporterFunction): void {
        this.transporterFn = transporterFn;
    }

    /**
     * set the tags provider to attach to the metric/stats
     * @param tagsProvider
     */
    public setTagsProvider(tagsProvider: TagsProviderInterface): void {
        this.tagsProvider = tagsProvider;
        this.tagsProviderFn = tagsProvider.populateTags;
    }

    /**
     * set the tags provider function to attach to the metric/stats
     * @param tagsProvider
     */
    public setTagsProviderFn(tagsProviderFn: TagsProviderFunction): void {
        this.tagsProviderFn = tagsProviderFn;
    }

    public getBrowser(): BrowserInfo {
        return this.browserInfo;
    }

    /**
     * register to window
     */
    public registerGlobals(registerToWindow: boolean = true): boolean {
        let browserDetection = new BrowserDetection(null);

        this.browserInfo = new BrowserInfo(browserDetection.getName(), browserDetection.getVersion());

        console.log(`CollectorJS.TfiStatsCollector: The browser type '${this.browserInfo.name} v${this.browserInfo.version}' was detected!`);

        if (!Boolean((<any>window).TfiStats) && registerToWindow) {
            console.log('CollectorJS.TfiStatsCollector: Hook registered');
            (<any>window).TfiStats = this;
        }

        //Register the function which will get the values independent of the browser
        if (browserDetection.isSafari()) {
            this.isLegacy = Number.parseInt(browserDetection.getVersion()) < 11;
        } else if (browserDetection.isChrome()) {
            this.isLegacy = Number.parseInt(browserDetection.getVersion().substr(0, 2)) < 75;
        } else if (browserDetection.isFirefox()) {
            this.isLegacy = Number.parseInt(browserDetection.getVersion()) < 66;
        } else {
            this.isLegacy = false;
        }

        console.log(`CollectorJS.TfiStatsCollector: Stats collector hooked`);
        return true;
    }

    //From opentok
    private calculateVideoScore(bytesReceivedInInterval: number, width: number, height: number) {
        let targetBitrateForPixelCount = (pixelCount) => {
            // power function maps resolution to target bitrate, based on rumor config
            // values, with r^2 = 0.98. We're ignoring frame rate, assume 30.
            let y = 2.069924867 * Math.pow(Math.log10(pixelCount), 0.6250223771);
            return Math.pow(10, y);
        };

        const MIN_VIDEO_BITRATE = 30000;

        let bitrate = 8 * bytesReceivedInInterval;
        let pixelCount = width * height;
        let targetBitrate = targetBitrateForPixelCount(pixelCount);

        if (pixelCount <= 0)
            return 0;

        if (bitrate < MIN_VIDEO_BITRATE) {
            return 0;
        }
        bitrate = Math.min(bitrate, targetBitrate);
        let score =
            (Math.log(bitrate / MIN_VIDEO_BITRATE) /
                Math.log(targetBitrate / MIN_VIDEO_BITRATE)) * 4 + 1;
        return score;
    }

    //From twilio
    private calcMos(rtt: number, jitter: number, fractionLost: number, rFactor: number): number {
        if (!TfiStatsCollector.isPositiveNumber(rtt) ||
            !TfiStatsCollector.isPositiveNumber(jitter) ||
            !TfiStatsCollector.isPositiveNumber(fractionLost)) {
            return null;
        }

        const mos = 1 + (0.035 * rFactor) + (0.000007 * rFactor) *
            (rFactor - 60) * (100 - rFactor);

        // Make sure MOS is in range
        const isValid = (mos >= 1.0 && mos < 4.6);
        return isValid ? mos : 0;
    }

    private calculateRFactor(rtt: number, jitter: number, fractionLost: number): number {
        const effectiveLatency = rtt + (jitter * 2) + 10;
        let rFactor = 0;

        switch (true) {
            case effectiveLatency < 160:
                rFactor = rfactorConstants.r0 - (effectiveLatency / 40);
                break;
            case effectiveLatency < 1000:
                rFactor = rfactorConstants.r0 - ((effectiveLatency - 120) / 10);
                break;
            case effectiveLatency >= 1000:
                rFactor = rfactorConstants.r0 - ((effectiveLatency) / 100);
                break;
        }

        let multiplier = .01;
        switch (true) {
            case fractionLost === -1:
                multiplier = 0;
                rFactor = 0;
                break;
            case fractionLost <= (rFactor / 2.5):
                multiplier = 2.5;
                break;
            case fractionLost > (rFactor / 2.5) && fractionLost < 100:
                multiplier = .25;
                break;
        }

        rFactor -= (fractionLost * multiplier);
        return rFactor;
    }

    private static isPositiveNumber(n: number) {
        return typeof n === 'number' && !isNaN(n) && isFinite(n) && n >= 0;
    }

    private computeDiff(currentValue: any, prevValue: any, valueField: string, tsField: string): number {
        if (!currentValue || !prevValue) {
            return 0;
        }

        let cur = currentValue[valueField];
        let prev = prevValue[valueField];

        if (!cur) {
            return 0;
        }
        if (!prev) {
            return 0;
        }

        let curTs = currentValue[tsField];
        let prevTs = prevValue[tsField];

        let deltaTime = (curTs - prevTs);
        if (deltaTime <= 0) {
            return cur;
        }

        return Math.floor((cur - prev) * 1000 / deltaTime);
    }

    private computeStats(rtcStats: WebRTCStats, candidatePairId: string): WebRTCStats {
        //Initialize all the fields
        let diffStats: WebRTCStats = new WebRTCStats();

        let webRTCAudioStat = this.ssrcLocalAudioStatsMap.get(rtcStats.localAudioSsrc);
        if (webRTCAudioStat) {
            diffStats.audio.local.bytesSent = this.computeDiff(rtcStats.audio.local, webRTCAudioStat.local,
                'bytesSent', 'rtpTimestamp');
            diffStats.audio.local.packetsSent = this.computeDiff(rtcStats.audio.local, webRTCAudioStat.local,
                'packetsSent', 'rtpTimestamp');
            diffStats.audio.local.packetsLost = this.computeDiff(rtcStats.audio.local, webRTCAudioStat.local,
                'packetsLost', 'rtpTimestamp');
            diffStats.audio.local.jitter = Math.abs(this.computeDiff(rtcStats.audio.local, webRTCAudioStat.local,
                'jitter', 'rtpTimestamp'));
        } else {
            diffStats.audio.local = Object.assign({}, rtcStats.audio.local);
        }
        webRTCAudioStat = this.ssrcRemoteAudioStatsMap.get(rtcStats.remoteAudioSsrc);
        if (webRTCAudioStat) {
            diffStats.audio.remote.packetsReceived = this.computeDiff(rtcStats.audio.remote, webRTCAudioStat.remote,
                'packetsReceived', 'rtpTimestamp');
            diffStats.audio.remote.bytesReceived = this.computeDiff(rtcStats.audio.remote, webRTCAudioStat.remote,
                'bytesReceived', 'rtpTimestamp');
        } else {
            diffStats.audio.remote = Object.assign({}, rtcStats.audio.remote);
        }

        let webRTCVideoStat = this.ssrcLocalVideoStatsMap.get(rtcStats.localVideoSsrc);
        if (webRTCVideoStat) {
            diffStats.video.local.bytesSent = this.computeDiff(rtcStats.video.local, webRTCVideoStat.local,
                'bytesSent', 'rtpTimestamp');
            diffStats.video.local.packetsSent = this.computeDiff(rtcStats.video.local, webRTCVideoStat.local,
                'packetsSent', 'rtpTimestamp');
            diffStats.video.local.qp = this.computeDiff(rtcStats.video.local, webRTCVideoStat.local,
                'qp', 'rtpTimestamp');
            diffStats.video.local.packetsLost = this.computeDiff(rtcStats.video.local, webRTCVideoStat.local,
                'packetsLost', 'rtpTimestamp');
        } else {
            diffStats.video.local = Object.assign({}, rtcStats.video.local);
        }

        webRTCVideoStat = this.ssrcRemoteVideoStatsMap.get(rtcStats.remoteVideoSsrc);
        if (webRTCVideoStat) {
            diffStats.video.remote.packetsReceived = this.computeDiff(rtcStats.video.remote, webRTCVideoStat.remote,
                'packetsReceived', 'rtpTimestamp');
            diffStats.video.remote.bytesReceived = this.computeDiff(rtcStats.video.remote, webRTCVideoStat.remote,
                'bytesReceived', 'rtpTimestamp');
        } else {
            diffStats.video.remote = Object.assign({}, rtcStats.video.remote);
        }

        if (candidatePairId) {
            let webRTCNetworkStat = this.transportStatsMap.get(candidatePairId);
            if (webRTCNetworkStat) {
                diffStats.network.bytesReceived = this.computeDiff(rtcStats.network, webRTCNetworkStat,
                    'bytesReceived', 'timestamp');
                diffStats.network.bytesSent = this.computeDiff(rtcStats.network, webRTCNetworkStat,
                    'bytesSent', 'timestamp');
            } else {
                diffStats.network = Object.assign({}, rtcStats.network);
            }
        }

        diffStats.network.rtt = rtcStats.network.rtt || 0;
        diffStats.network.availableSendBandwidth = rtcStats.network.availableSendBandwidth || 0;

        if (diffStats.audio.remote.packetsReceived && diffStats.audio.local.packetsLost) {
            diffStats.audio.local.packetsLostFraction = ((diffStats.audio.remote.packetsReceived > 0) ?
                (diffStats.audio.local.packetsLost / diffStats.audio.remote.packetsReceived) * 100 : 0);
        } else {
            diffStats.audio.local.packetsLostFraction = 0;
        }

        if (diffStats.video.remote.packetsReceived && diffStats.video.local.packetsLost) {
            diffStats.video.local.packetsLostFraction = ((diffStats.video.remote.packetsReceived > 0) ?
                (diffStats.video.local.packetsLost / diffStats.video.remote.packetsReceived) * 100 : 0);
        } else {
            diffStats.video.local.packetsLostFraction = 0;
        }

        diffStats.network.rtt = Math.abs(diffStats.network.rtt);
        diffStats.audio.local.packetsLostFraction = Math.abs(diffStats.audio.local.packetsLostFraction);

        rtcStats.audio.local.rFactor = this.calculateRFactor(diffStats.network.rtt,
            diffStats.audio.local.jitter,
            diffStats.audio.local.packetsLostFraction);
        diffStats.audio.local.rFactor = rtcStats.audio.local.rFactor;
        rtcStats.audio.local.mos = this.calcMos(diffStats.network.rtt, diffStats.audio.local.jitter,
            diffStats.audio.local.packetsLostFraction, diffStats.audio.local.rFactor);
        diffStats.audio.local.mos = rtcStats.audio.local.mos;

        rtcStats.video.local.mos = this.calculateVideoScore(diffStats.video.remote.bytesReceived,
            rtcStats.video.remote.frameWidth, rtcStats.video.remote.frameHeight);
        diffStats.video.local.mos = rtcStats.video.local.mos;
        diffStats.video.remote.frameWidth = rtcStats.video.remote.frameWidth;
        diffStats.video.remote.frameHeight = rtcStats.video.remote.frameHeight;
        diffStats.video.local.frameWidth = rtcStats.video.local.frameWidth;
        diffStats.video.local.frameHeight = rtcStats.video.local.frameHeight;

        if (rtcStats.remoteVideoSsrc)
            this.ssrcRemoteVideoStatsMap.set(rtcStats.remoteVideoSsrc, rtcStats.video);
        if (rtcStats.remoteAudioSsrc)
            this.ssrcRemoteAudioStatsMap.set(rtcStats.remoteAudioSsrc, rtcStats.audio);
        if (rtcStats.localVideoSsrc)
            this.ssrcLocalVideoStatsMap.set(rtcStats.localVideoSsrc, rtcStats.video);
        if (rtcStats.localAudioSsrc)
            this.ssrcLocalAudioStatsMap.set(rtcStats.localAudioSsrc, rtcStats.audio);
        if (candidatePairId && rtcStats.network) {
            this.transportStatsMap.set(candidatePairId, rtcStats.network);
        }

        return diffStats;
    }

    //Compatibility for all browsers
    private polyFillStats(statsReport: any): any {
        if (!statsReport || Array.isArray(statsReport) &&
            Object.prototype.toString.call(statsReport.values) !== '[object Array]') {
            return null;
        }
        const neutralResults = [];
        if (typeof (<any>window).RTCStatsReport !== 'undefined' && statsReport instanceof (<any>window).RTCStatsReport) {
            statsReport.forEach((value, key) => {
                neutralResults.push({ key, value });
            });
        } else if (Object.keys(statsReport).length > 0) {
            Object.keys(statsReport).forEach(key => {
                neutralResults.push({
                    key,
                    value: statsReport[key]
                });
            });
        } else {
            // console.log('Unknown stats results format, returning unmodified', statsReport);
            return statsReport;
        }
        return neutralResults;
    }

    /**
     * pushStats
       report: RTCStatsReport
     */
    public pushStats(statsReport: RTCStatsReport): Promise<StatsProcessingStatus> {
        let rtcStats: WebRTCStats = new WebRTCStats();
        let selectedCandidatePairId: string = null;
        const neutralResults = this.polyFillStats(statsReport);
        if (neutralResults == null) {
            console.log("Unknown stats format");
            return Promise.reject("Unknown stats format");
        }
        //Maintain small set of trans
        let candidatesMap = new Map<string, any>();

        try {
            for (let i = 0; i < neutralResults.length; i++) {
                const kv = neutralResults[i];
                const stat = kv.value;
                const type = stat.type.replace('-', '');
                if (stat.remoteId) {
                    const remote = statsReport.get(stat.remoteId);
                    if (remote && remote.roundTripTime) {
                        rtcStats.network.rtt = remote.roundTripTime * 1000;
                    }
                }

                switch (type) {
                    case 'remoteinboundrtp':
                    case 'inboundrtp':
                        switch (stat.kind) {
                            case "video":
                                rtcStats.video.remote.rtpTimestamp = stat.timestamp;
                                rtcStats.remoteVideoSsrc = stat.ssrc;
                                rtcStats.video.local.packetsLost = stat.packetsLost;
                                rtcStats.video.remote.bytesReceived = stat.bytesReceived;
                                rtcStats.video.remote.packetsReceived = stat.packetsReceived;
                                rtcStats.video.remote.framesDropped = stat.framesDropped;
                                rtcStats.video.remote.framesReceived = stat.framesReceived;
                                rtcStats.video.remote.frameWidth = stat.frameWidth || 0;
                                rtcStats.video.remote.frameHeight = stat.frameHeight || 0;

                                break;
                            case "audio":
                                rtcStats.audio.remote.rtpTimestamp = stat.timestamp;
                                rtcStats.remoteAudioSsrc = stat.ssrc;
                                rtcStats.audio.local.packetsLost = stat.packetsLost;
                                rtcStats.audio.remote.packetsReceived = stat.packetsReceived;
                                //comes in seconds, convert to milliseconds
                                rtcStats.audio.local.jitter = (stat.jitter * 1000);
                                rtcStats.audio.remote.bytesReceived = stat.bytesReceived;
                                break;
                        }
                        break;
                    case 'remoteoutboundrtp':
                    case 'outboundrtp':
                        switch (stat.kind) {
                            case "video":
                                rtcStats.video.local.rtpTimestamp = stat.timestamp;
                                rtcStats.localVideoSsrc = stat.ssrc;
                                rtcStats.video.local.packetsSent = stat.packetsSent;
                                rtcStats.video.local.bytesSent = stat.bytesSent;
                                rtcStats.video.local.qp = stat.qpSum;
                                rtcStats.video.local.frameWidth = stat.frameWidth || 0;
                                rtcStats.video.local.frameHeight = stat.frameHeight || 0;
                                break;
                            case "audio":
                                rtcStats.audio.local.rtpTimestamp = stat.timestamp;
                                rtcStats.localAudioSsrc = stat.ssrc;
                                rtcStats.audio.local.packetsSent = stat.packetsSent;
                                rtcStats.audio.local.bytesSent = stat.bytesSent;
                                break;
                        }
                        break;
                    case 'track':
                        switch (stat.kind) {
                            case "video":
                                if (stat.remoteSource) {
                                    rtcStats.video.remote.trackTimestamp = stat.timestamp;
                                } else {
                                    rtcStats.video.local.trackTimestamp = stat.timestamp;
                                    rtcStats.video.local.framesSent = stat.framesSent;
                                }
                                break;
                            case "audio":
                                if (stat.remoteSource) {
                                    rtcStats.audio.remote.trackTimestamp = stat.timestamp;
                                    rtcStats.audio.remote.audioLevelReceived = stat.audioLevel * 1000;
                                } else {
                                    rtcStats.audio.local.trackTimestamp = stat.timestamp;
                                    rtcStats.audio.local.audioLevelSent = stat.audioLevel * 1000;
                                }
                                break;
                        }
                        break;
                    case 'transport':
                        if (stat.dtlsState === 'connected' || stat.active == 'true') {
                            selectedCandidatePairId = stat.selectedCandidatePairId;
                        }
                        break;
                    case 'candidatepair':
                        candidatesMap.set(stat.id, stat);
                        break;
                }
            }
        } catch (e) {
            console.error(`Unsupported key:${e}`, e);
            return Promise.reject(`Unsupported key:${e}`);
        }

        try {
            //Need optimization here... cannot filter nor do anything with .get() chrome throws error
            if (selectedCandidatePairId) {
                let selectedCandidatePair = null;
                if (candidatesMap.has(selectedCandidatePairId)) {
                    selectedCandidatePair = candidatesMap.get(selectedCandidatePairId);
                    if (!rtcStats.network.rtt) {
                        rtcStats.network.rtt = selectedCandidatePair.currentRoundTripTime * 1000;
                    }

                    rtcStats.network.timestamp = selectedCandidatePair.timestamp;
                    rtcStats.network.bytesReceived = selectedCandidatePair.bytesReceived;
                    rtcStats.network.bytesSent = selectedCandidatePair.bytesSent;
                    rtcStats.network.availableSendBandwidth = selectedCandidatePair.availableOutgoingBitrate;
                }
                if (selectedCandidatePair) {
                    for (let i = 0; i < neutralResults.length; i++) {
                        const kv = neutralResults[i];
                        const stat = kv.value;

                        if (stat.id == selectedCandidatePair.localCandidateId) {
                            if (stat.address) {
                                rtcStats.network.localAddress = stat.address;
                            } else {
                                rtcStats.network.localAddress = `${stat.ip}:${stat.port}`;
                            }
                        }
                        if (stat.id == selectedCandidatePair.remoteCandidateId) {
                            if (stat.address) {
                                rtcStats.network.remoteAddress = stat.address;
                            } else {
                                rtcStats.network.remoteAddress = `${stat.ip}:${stat.port}`;
                            }
                        }
                    }
                }
            }
        } catch (e) {
            console.error(`Unsupported key:${e}`, e);
        }

        let computedStats = this.computeStats(rtcStats, selectedCandidatePairId);
        if (this.tagsProviderFn == null) {
            this.setTagsProvider(new MockTagsProvider());
        }
        if (this.transporterFn == null) {
            this.setTransport(new MockTransport());
        }

        //We get the stats here
        this.tagsProviderFn()
            .then(tags => {
                if (!tags.has("Location")) {
                    return Promise.reject(`Location tag is not set`);
                }

                if (rtcStats.localAudioSsrc)
                    tags.set('LocalAudioSSRC', rtcStats.localAudioSsrc.toString());
                if (rtcStats.localVideoSsrc)
                    tags.set('LocalVideoSSRC', rtcStats.localVideoSsrc.toString());
                if (rtcStats.remoteAudioSsrc)
                    tags.set('RemoteAudioSSRC', rtcStats.remoteAudioSsrc.toString());
                if (rtcStats.remoteVideoSsrc)
                    tags.set('RemoteVideoSSRC', rtcStats.remoteVideoSsrc.toString());
                if (rtcStats.network.localAddress)
                    tags.set('LocalAddress', rtcStats.network.localAddress);
                if (rtcStats.network.remoteAddress)
                    tags.set('RemoteAddress', rtcStats.network.remoteAddress);

                tags.set('BrowserName', `${this.browserInfo.name}`);
                tags.set('BrowserVersion', `${this.browserInfo.version}`);

                this.transporterFn({
                    stats: computedStats.getMetric(),
                    tagKeys: [...tags.keys()],
                    tagValues: [...tags.values()]
                })
                    .then(res => {
                        //console.log(`Stats sent successfully ${res.code} ${res.status}`);
                        return Promise.resolve({ status: res.status, code: res.code });
                    }).catch(err => {
                        console.error(err);
                        return Promise.reject(`Error on save ${err}`);
                    });
            }).catch(err => {
                console.error(err);
                return Promise.reject(`Error on save ${err}`);
            });
    }

    /**
     * pushEvents
     report: IObservedEvent
     */
    public pushEvents(event: IObservedEvent): void {
        //We get the events here
        console.log(event);
    }

    public cleanUp(): void {
        this.ssrcLocalVideoStatsMap.clear();
        this.ssrcRemoteVideoStatsMap.clear();
        this.ssrcLocalAudioStatsMap.clear();
        this.ssrcRemoteAudioStatsMap.clear();
        this.transportStatsMap.clear();
    }
}