import * as Bowser from "bowser";

import {
    CHROME,
    OPERA,
    FIREFOX,
    INTERNET_EXPLORER,
    EDGE,
    SAFARI,
    ELECTRON,
    REACT_NATIVE,
    UNKNOWN
} from './browsers';

/**
 * Maps the names of the browsers from bowser to the internal names defined in
 * ./browsers.ts
 */
const bowserNameToTfiName = {
    'Chrome': CHROME,
    'Chromium': CHROME,
    'Opera': OPERA,
    'Firefox': FIREFOX,
    'Internet Explorer': INTERNET_EXPLORER,
    'Microsoft Edge': EDGE,
    'Safari': SAFARI
};

/**
 * Browser name and version
 */
export class BrowserInfo {
    public readonly name: string;
    public readonly version: string;

    constructor(n:string,v:string){
        this.name = n;
        this.version = v;
    }
}

/**
 * detect if chromium
 * @private
 */
function _detectChromiumBased() : BrowserInfo {
    const userAgent = navigator.userAgent;

    if (Boolean((<any>window).chrome)
            && !userAgent.match(/Edge/) && userAgent.match(/Chrome/)) {
        const version = userAgent.match(/Chrome\/([\d.]+)/)[1];

        return new BrowserInfo(CHROME,version);
    }

    return null;
}

/**
 * detect if electron
 * @private
 */
function _detectElectron() : BrowserInfo {
    const userAgent = navigator.userAgent;

    if (userAgent.match(/Electron/)) {
        const version = userAgent.match(/Electron\/([\d.]+)/)[1];

        return new BrowserInfo(ELECTRON,version);
    }
}

/**
 * detect if react native
 * @private
 */
function _detectReactNative() : BrowserInfo {
    const match
        = navigator.userAgent.match(/\b(react[ \t_-]*native)(?:\/(\S+))?/i);
    let version;

    // If we're remote debugging a React Native app, it may be treated as
    // Chrome. Check navigator.product as well and always return some version
    // even if we can't get the real one.

    if (match || navigator.product === 'ReactNative') {
        let name;

        if (match && match.length > 2) {
            name = match[1];
            version = match[2];
        }
        name || (name = 'react-native');
        version || (version = 'unknown');

        return new BrowserInfo(name,version);
    }
}

/**
 * detect the browser
 * @private
 */
function _detect() : BrowserInfo {
    let browserInfo;
    const detectors = [
        _detectReactNative,
        _detectElectron
    ];

    // Try all browser detectors
    for (let i = 0; i < detectors.length; i++) {
        browserInfo = detectors[i]();
        if (browserInfo) {
            return browserInfo;
        }
    }

    const browser = Bowser.getParser(window.navigator.userAgent);
    const name = browser.getBrowserName();
    const version = browser.getBrowserVersion();

    if (name in bowserNameToTfiName) {
        return new BrowserInfo(bowserNameToTfiName[name], version);
    }

    // Detect other browsers with the Chrome engine, such as Vivaldi.
    browserInfo = _detectChromiumBased();
    if (browserInfo) {
        return browserInfo;
    }

    return new BrowserInfo(UNKNOWN,undefined);
}

/**
 * Browser detection.
 */
export class BrowserDetection {
    private readonly _name: string;
    private readonly _version: string;

    constructor(browserInfo: BrowserInfo) {
        let name, version;

        if (browserInfo == null) {
            const detectedBrowserInfo = _detect();

            name = detectedBrowserInfo.name;
            version = detectedBrowserInfo.version;
        } else if (browserInfo.name in bowserNameToTfiName) {
            name = bowserNameToTfiName[browserInfo.name];
            version = browserInfo.version;
        } else {
            name = UNKNOWN;
            version = undefined;
        }

        this._name = name;
        this._version = version;
    }

    /**
     * Get the name of the browser
     */
    getName(): string {
        return this._name;
    }

    /**
     * Check if chrome
     */
    isChrome(): boolean {
        return this._name === CHROME;
    }

    /**
     * Check if opera
     */
    isOpera(): boolean {
        return this._name === OPERA;
    }

    /**
     * Check if firefox
     */
    isFirefox(): boolean {
        return this._name === FIREFOX;
    }

    /**
     * Check if IE
     */
    isIExplorer(): boolean {
        return this._name === INTERNET_EXPLORER;
    }

    /**
     * Check if Edge
     */
    isEdge(): boolean {
        return this._name === EDGE;
    }

    /**
     * Check if safari
     */
    isSafari(): boolean {
        return this._name === SAFARI;
    }

    /**
     * Check if electron
     */
    isElectron(): boolean {
        return this._name === ELECTRON;
    }

    /**
     * Check if react native
     */
    isReactNative(): boolean {
        return this._name === REACT_NATIVE;
    }

    /**
     * Get browser version
     */
    getVersion(): string {
        return this._version;
    }
}