/**
 * Response from the transporter
 */
export class TransporterResponse {
    status: string;
    code: number;
}

/**
 * Function to transport metrics
 */
export type MetricsTransporterFunction = (stats: any) => Promise<TransporterResponse>;

/**
 * Transport interface
 */
export interface TransportInterface {
    push(stats: any): Promise<TransporterResponse>;
}

/**
 * Mock Transport for testing
 */
export class MockTransport implements TransportInterface {
    push(stats: any): Promise<TransporterResponse> {
        console.log(stats);
        return Promise.resolve({ status: "Success", code: 200 });
    }
}