export class StatsProcessingStatus {
    status: string;
    code: number;
}

export class WebRTCRemoteStat {
    constructor(){
        this.bytesReceived = 0;
        this.packetsReceived = 0;
    }

    /**
     * Bytes received per second (adjusted as per interval)
     */
    bytesReceived: number;

    /**
     * Number of packets received per second (adjusted as per interval)
     */
    packetsReceived: number;

    /**
     * Timestamp of the capture for inbound audio rtp
     */
    rtpTimestamp: number;

    /**
     * Timestamp of the capture for remote track
     */
    trackTimestamp: number;
}

export class WebRTCLocalStat {
    constructor(){
        this.bytesSent = 0;
        this.packetsSent = 0;
        this.packetsLost = 0;
        this.packetsLostFraction = 0;
    }

    /**
     * Bytes sent per second (adjusted as per interval)
     */
    bytesSent: number;

    /**
     * Number of packets sent per second (adjusted as per interval)
     */
    packetsSent: number;

    /**
     * Timestamp of the capture for inbound video rtp
     */
    rtpTimestamp: number;

    /**
     * Timestamp of the capture for remote track
     */
    trackTimestamp: number;

    /**
     * Number of packets lost per second (adjusted as per interval)
     */
    packetsLost: number;

    /**
     * Packets lost to inbound packets ratio per second (adjusted as per interval)
     */
    packetsLostFraction: number;
}

export class WebRTCVideoLocal extends WebRTCLocalStat {
    constructor(){
        super();
        this.framesSent = 0;
        this.qp = 0;
        this.mos = 0;
        this.frameWidth = 0;
        this.frameHeight = 0;
    }

    /**
     * Frame width
     */
    frameWidth: number;

    /**
     * Frame height
     */
    frameHeight: number;

    /**
     * Mean opinion score
     */
    mos: number;

    /**
     * Framerate
     */
    framesSent: number;

    /**
     * Average Quantization parameter
     */
    qp: number;
}

export class WebRTCVideoRemote extends WebRTCRemoteStat {
    constructor(){
        super();
        this.framesDropped = 0;
        this.framesReceived = 0;
        this.frameWidth = 0;
        this.frameHeight = 0;
    }

    /**
     * Frame width
     */
    frameWidth: number;

    /**
     * Frame height
     */
    frameHeight: number;

    /**
     * Frames dropped
     */
    framesDropped: number;

    /**
     * Frames received
     */
    framesReceived: number;
}

export class WebRTCAudioLocal  extends WebRTCLocalStat {
    constructor(){
        super();
        this.audioLevelSent = 0;
        this.jitter = 0;
        this.mos = 0;
        this.rFactor = 0;
    }
    /**
     * Audio Energy level
     */
    audioLevelSent: number;

    /**
     * Mean opinion score
     */
    mos: number;

    /**
     * R Factor
     */
    rFactor: number;

    /**
     * Packets delay variation
     */
    jitter: number;
}

export class WebRTCAudioRemote extends WebRTCRemoteStat {
    constructor(){
        super();
        this.audioLevelReceived = 0;
    }

    /**
     * Audio Energy level
     */
    audioLevelReceived: number;
}

export class WebRTCVideoStat {
    constructor(){
        this.remote = new WebRTCVideoRemote();
        this.local = new WebRTCVideoLocal();
    }
    /**
     * Remote/Inbound RTP or Track stats
     */
    remote: WebRTCVideoRemote;

    /**
     * Local/Outbound RTP or Track stats
     */
    local: WebRTCVideoLocal;
}

export class WebRTCAudioStat {
    constructor(){
        this.remote = new WebRTCAudioRemote();
        this.local = new WebRTCAudioLocal();
    }
    /**
     * Remote/Inbound RTP or Track stats
     */
    remote: WebRTCAudioRemote;

    /**
     * Local/Outbound RTP or Track stats
     */
    local: WebRTCAudioLocal;
}

export class WebRTCNetworkStat {
    constructor(){
        this.bytesReceived = 0;
        this.bytesSent = 0;
        this.availableSendBandwidth = 0;
        this.rtt = 0;
    }

    /**
     * Bytes received per second (adjusted as per interval)
     */
    bytesReceived: number;

    /**
     * Bytes sent per second (adjusted as per interval)
     */
    bytesSent: number;

    /**
     * Available send bandwidth per second (adjusted as per interval)
     */
    availableSendBandwidth: number;

    /**
     * Round trip time
     */
    rtt: number;

    /**
     * Local address port
     */
    localAddress: string;

    /**
     * Remote address port
     */
    remoteAddress: string;

    /**
     * Timestamp of the network ICE
     */
    timestamp: number;
}

export class WebRTCStats {
    audio: WebRTCAudioStat;
    video: WebRTCVideoStat;
    network: WebRTCNetworkStat;
    localAudioSsrc: string;
    localVideoSsrc: string;
    remoteAudioSsrc: string;
    remoteVideoSsrc: string;

    constructor(){
        this.audio = new WebRTCAudioStat();
        this.video = new WebRTCVideoStat();
        this.network = new WebRTCNetworkStat();
    }

    getMetric(): any {
        return {
            audio: {
                local: {
                    audioLevelSent: this.audio.local.audioLevelSent || 0,
                    mos: this.audio.local.mos || 0,
                    rFactor: this.audio.local.rFactor || 0,
                    bytesSent: this.audio.local.bytesSent || 0,
                    jitter: this.audio.local.jitter || 0,
                    packetsLost: this.audio.local.packetsLost || 0,
                    packetsLostFraction: this.audio.local.packetsLostFraction || 0,
                    packetsSent: this.audio.local.packetsSent|| 0
                },
                remote: {
                    audioLevelReceived: this.audio.remote.audioLevelReceived || 0,
                    bytesReceived: this.audio.remote.bytesReceived || 0,
                    packetsReceived: this.audio.remote.packetsReceived || 0
                }
            },
            video: {
                local: {
                    framesSent: this.video.local.framesSent || 0,
                    qp: this.video.local.qp || 0,
                    bytesSent: this.video.local.bytesSent || 0,
                    packetsLost: this.video.local.packetsLost || 0,
                    packetsLostFraction: this.video.local.packetsLostFraction || 0,
                    packetsSent: this.video.local.packetsSent || 0,
                    mos: this.video.local.mos
                },
                remote: {
                    framesDropped: this.video.remote.framesDropped || 0,
                    framesReceived: this.video.remote.framesReceived || 0,
                    bytesReceived: this.video.remote.bytesReceived || 0,
                    packetsReceived: this.video.remote.packetsReceived || 0,
                    frameWidth: this.video.remote.frameWidth || 0,
                    frameHeight: this.video.remote.frameHeight || 0
                }
            },
            network: {
                bytesReceived: this.network.bytesReceived || 0,
                bytesSent: this.network.bytesSent || 0,
                availableSendBandwidth: this.network.availableSendBandwidth || 0,
                rtt: this.network.rtt || 0
            }
        }
    }
}