/**
 * Tags provider function
 */
export type TagsProviderFunction = () => Promise<Map<string,string>>;

/**
 * Tags interface
 */
export interface TagsProviderInterface {
    /**
     * Populate tags and provide response as a map
     */
    populateTags(): Promise<Map<string,string>>;
}

/**
 * Mock tags provider
 */
export class MockTagsProvider implements TagsProviderInterface {
    populateTags(): Promise<Map<string, string>> {
        const map = new Map<string,string>();
        map.set("mock", "true");
        return Promise.resolve(map);
    }
}